<template>
  <div class="nt-page">
    <HomeNav id="nt-nav" />
    <div class="nt-wrap">
      <header class="nt-header"><div><router-link to="/target-network" class="nt-back"><i class="fa fa-angle-left" aria-hidden="true"></i> กลับไปเครือข่าย</router-link><h1>จัดการเป้าหมาย <span class="nt-demo">MOCKUP</span></h1><p>เตรียมบัญชีและแฮชแท็ก เลือกข้อมูลที่ต้องการเก็บ แล้วเข้าคิวไว้ล่วงหน้า</p></div><button id="nt-add" class="nt-primary" @click="openForm()"><i class="fa fa-plus" aria-hidden="true"></i> เพิ่มเป้าหมาย</button></header>
      <div class="nt-notice"><i class="fa fa-flask" aria-hidden="true"></i><span>พื้นที่ทดลอง · บันทึกเฉพาะในเบราว์เซอร์นี้ การเข้าคิวเป็นการจำลอง ยังไม่เรียกบอตหรือฐานข้อมูลจริง</span></div>
      <div v-if="message" class="nt-message" role="status"><span>{{ message }}</span><button aria-label="ปิดข้อความ" @click="message = ''">×</button></div>
      <div class="nt-stats"><div><span class="nt-stat-icon mint"><i class="fa fa-crosshairs" aria-hidden="true"></i></span><span>เป้าหมายทั้งหมด<strong>{{ targets.length }}</strong></span></div><div><span class="nt-stat-icon purple"><i class="fa fa-clock-o" aria-hidden="true"></i></span><span>อยู่ในคิวจำลอง<strong>{{ countStatus('queued') }}</strong></span></div><div><span class="nt-stat-icon blue"><i class="fa fa-database" aria-hidden="true"></i></span><span>มีข้อมูลตัวอย่างพร้อมใช้<strong>{{ countStatus('ready') }}</strong></span></div><div><span class="nt-stat-icon amber"><i class="fa fa-pause" aria-hidden="true"></i></span><span>พักการเก็บ<strong>{{ countStatus('paused') }}</strong></span></div></div>
      <div class="nt-layout">
        <main class="nt-card nt-list">
          <div class="nt-list-heading"><div><h2>รายการเป้าหมาย</h2><span>{{ filteredTargets.length }} จาก {{ targets.length }} รายการ</span></div><div class="nt-tabs" role="group" aria-label="ประเภทเป้าหมาย"><button v-for="tab in typeTabs" :key="tab.key" :class="{ active: typeFilter === tab.key }" :aria-pressed="typeFilter === tab.key" @click="typeFilter = tab.key">{{ tab.label }}</button></div></div>
          <div class="nt-toolbar"><div class="nt-search"><i class="fa fa-search" aria-hidden="true"></i><input v-model="search" type="search" placeholder="ค้นหาชื่อ URL หรือแฮชแท็ก" aria-label="ค้นหาเป้าหมาย" /></div><select v-model="platformFilter" aria-label="กรองแพลตฟอร์ม"><option value="all">ทุกแพลตฟอร์ม</option><option v-for="platform in platforms" :key="platform" :value="platform">{{ platform }}</option></select><select v-model="statusFilter" aria-label="กรองสถานะ"><option value="all">ทุกสถานะ</option><option v-for="(label, status) in statusLabels" :key="status" :value="status">{{ label }}</option></select></div>
          <div class="nt-selection"><label><input type="checkbox" :checked="allVisibleSelected" :indeterminate.prop="selectedVisibleCount > 0 && !allVisibleSelected" :disabled="!filteredTargets.length" @change="selectVisible($event.target.checked)" /> เลือกที่แสดงทั้งหมด</label><span>{{ selectedIds.length ? 'เลือก ' + selectedIds.length + ' รายการ' : 'เลือกเป้าหมายเพื่อเตรียมดึงข้อมูลพร้อมกัน' }}</span><button class="nt-small-primary" :disabled="!queueableSelected.length" @click="enqueue(queueableSelected)"><i class="fa fa-play" aria-hidden="true"></i> เข้าคิวจำลอง{{ queueableSelected.length ? ' (' + queueableSelected.length + ')' : '' }}</button><button v-if="selectedIds.length" class="nt-text" @click="selectedIds = []">ล้าง</button></div>
          <div class="nt-table-scroll"><table><thead><tr><th scope="col"><span class="nt-sr">เลือก</span></th><th scope="col">เป้าหมาย</th><th scope="col">ข้อมูลที่ต้องการ</th><th scope="col">สถานะ</th><th scope="col">อัปเดตตัวอย่างล่าสุด</th><th scope="col">จัดการ</th></tr></thead><tbody><tr v-for="target in filteredTargets" :key="target.id" :class="{ active: activeId === target.id }"><td><input v-model="selectedIds" type="checkbox" :value="target.id" :aria-label="'เลือก ' + target.name" /></td><td><button class="nt-person" @click="activeId = target.id"><span class="nt-avatar" :class="target.kind === 'hashtag' ? 'purple' : 'mint'">{{ target.kind === 'hashtag' ? '#' : target.name.charAt(0) }}</span><span><strong>{{ target.name }}</strong><small>{{ target.platform }} · {{ target.kind === 'hashtag' ? '#' + target.value : target.value }}</small></span></button><div v-if="target.tags.length" class="nt-tags"><span v-for="tag in target.tags" :key="tag">{{ tag }}</span></div></td><td><div class="nt-scopes"><span v-for="scope in target.scopes.slice(0, 2)" :key="scope">{{ scopeLabel(scope) }}</span><span v-if="target.scopes.length > 2">+{{ target.scopes.length - 2 }}</span></div><small class="nt-muted">ย้อนหลัง {{ target.days }} วัน · {{ target.depth }} ชั้น</small></td><td><span class="nt-status" :class="target.status"><span></span>{{ statusLabels[target.status] }}</span></td><td><span class="nt-date">{{ target.updatedLabel || 'ยังไม่มีข้อมูล' }}</span></td><td><button class="nt-icon-button" :aria-label="'แก้ไข ' + target.name" :disabled="target.status === 'queued'" @click="openForm(target)"><i class="fa fa-pencil" aria-hidden="true"></i></button><button class="nt-icon-button" :aria-label="'ดูรายละเอียด ' + target.name" @click="activeId = target.id"><i class="fa fa-angle-right" aria-hidden="true"></i></button></td></tr><tr v-if="!filteredTargets.length"><td colspan="6"><div class="nt-empty"><i class="fa fa-search" aria-hidden="true"></i><strong>ไม่พบเป้าหมายที่ตรงกับเงื่อนไข</strong><button class="nt-text" @click="clearFilters">ล้างตัวกรอง</button></div></td></tr></tbody></table></div>
          <div class="nt-list-footer"><i class="fa fa-info-circle" aria-hidden="true"></i> ตรวจข้อมูลใน MongoDB ก่อน และเก็บเพิ่มเฉพาะส่วนที่ขาดหรือเก่า <span>ข้อมูลจำลอง</span></div>
        </main>
        <aside v-if="activeTarget" class="nt-card nt-detail" aria-label="รายละเอียดเป้าหมาย">
          <div class="nt-detail-title"><h2>แผนการเก็บข้อมูล</h2><span class="nt-demo">PREVIEW</span></div>
          <div class="nt-detail-person"><span class="nt-avatar" :class="activeTarget.kind === 'hashtag' ? 'purple' : 'mint'">{{ activeTarget.kind === 'hashtag' ? '#' : activeTarget.name.charAt(0) }}</span><div><h3>{{ activeTarget.name }}</h3><span>{{ activeTarget.platform }} · {{ activeTarget.kind === 'hashtag' ? 'แฮชแท็ก' : 'บัญชีเป้าหมาย' }}</span></div></div>
          <div class="nt-detail-value">{{ activeTarget.kind === 'hashtag' ? '#' + activeTarget.value : activeTarget.value }}</div>
          <span class="nt-status" :class="activeTarget.status"><span></span>{{ statusLabels[activeTarget.status] }}</span>
          <dl class="nt-settings"><div><dt>ช่วงข้อมูล</dt><dd>ย้อนหลัง {{ activeTarget.days }} วัน</dd></div><div><dt>ความลึกเครือข่าย</dt><dd>{{ activeTarget.depth }} ชั้น</dd></div><div><dt>ลำดับความสำคัญ</dt><dd>{{ priorityLabels[activeTarget.priority] }}</dd></div><div><dt>รอบการเก็บ</dt><dd>{{ frequencyLabels[activeTarget.frequency] }}</dd></div></dl>
          <h4>ขอบเขตที่เลือก</h4><div class="nt-detail-scopes"><span v-for="scope in activeTarget.scopes" :key="scope"><i class="fa fa-check" aria-hidden="true"></i> {{ scopeLabel(scope) }}</span></div>
          <h4>ลำดับการทำงานที่วางไว้</h4><ol class="nt-flow"><li><b>01</b><div><strong>ตรวจข้อมูลเดิมใน MongoDB</strong><p>{{ activeTarget.kind === 'account' ? 'ค้นหา target_list และ user_posts ของบัญชี' : 'ค้นหาโพสต์ใน user_posts ที่มีแฮชแท็กนี้' }}</p></div></li><li><b>02</b><div><strong>เตรียมกราฟจากข้อมูลที่มี</strong><p>แปลงบัญชี โพสต์ และปฏิสัมพันธ์เข้า Neo4j</p></div></li><li><b>03</b><div><strong>ให้บอตเก็บข้อมูลเพิ่ม</strong><p>ทำเบื้องหลังเมื่อข้อมูลขาดหรือเก่า</p></div></li></ol>
          <p v-if="activeTarget.note" class="nt-note"><b>หมายเหตุ</b>{{ activeTarget.note }}</p>
          <div v-if="activeTarget.status === 'queued'" class="nt-queued-info" role="status"><i class="fa fa-clock-o" aria-hidden="true"></i> อยู่ในคิวจำลอง ไม่มีการดึงข้อมูลจริง<button class="nt-text" @click="cancelQueue(activeTarget)">ยกเลิกคิวจำลอง</button></div>
          <template v-else><button class="nt-primary nt-full" :disabled="activeTarget.status === 'paused'" @click="enqueue([activeTarget])"><i class="fa fa-play" aria-hidden="true"></i> เข้าคิวดึงข้อมูลจำลอง</button><div class="nt-detail-actions"><button class="nt-text" @click="openForm(activeTarget)">แก้ไขเป้าหมาย</button><button class="nt-text" @click="togglePause(activeTarget)">{{ activeTarget.status === 'paused' ? 'เปิดใช้งาน' : 'พักการเก็บ' }}</button></div></template>
        </aside>
      </div>
      <b-modal v-model="formOpen" :title="editingId ? 'แก้ไขเป้าหมาย' : 'เพิ่มเป้าหมายใหม่'" size="lg" hide-footer :no-close-on-backdrop="true" return-focus="#nt-add" @shown="focusName">
        <form class="nt-form" @submit.prevent="saveTarget">
          <p class="nt-form-intro">เตรียมรายการและขอบเขตการเก็บไว้ก่อน บันทึกแล้วเลือกเข้าคิวได้ภายหลัง</p>
          <div class="nt-form-tabs" role="group" aria-label="ชนิดเป้าหมาย"><button type="button" :class="{ active: form.kind === 'account' }" :aria-pressed="form.kind === 'account'" @click="setKind('account')"><i class="fa fa-user" aria-hidden="true"></i> บัญชี / เพจ</button><button type="button" :class="{ active: form.kind === 'hashtag' }" :aria-pressed="form.kind === 'hashtag'" @click="setKind('hashtag')"># แฮชแท็ก</button></div>
          <div class="nt-form-grid"><div><label for="nt-name">ชื่อเรียกเป้าหมาย <span>*</span></label><input id="nt-name" ref="nameInput" v-model.trim="form.name" required maxlength="100" placeholder="เช่น สมชาย ก. / ประเด็นเมืองน่าอยู่" /></div><div><label for="nt-platform">แพลตฟอร์ม <span>*</span></label><select id="nt-platform" v-model="form.platform"><option v-for="platform in platforms" :key="platform" :value="platform">{{ platform }}</option></select></div><div class="nt-wide"><label for="nt-value">{{ form.kind === 'account' ? 'URL โปรไฟล์หรือเพจ' : 'แฮชแท็ก' }} <span>*</span></label><input id="nt-value" v-model.trim="form.value" required maxlength="500" :type="form.kind === 'account' ? 'url' : 'text'" :placeholder="form.kind === 'account' ? 'https://www.facebook.com/username' : '#เมืองน่าอยู่'" /><small>{{ form.kind === 'account' ? 'URL ต้องตรงกับแพลตฟอร์มที่เลือก ระบบจะตรวจรายการซ้ำก่อนบันทึก' : 'ระบุแฮชแท็กเดียว ไม่เว้นวรรค ใส่หรือไม่ใส่ # ก็ได้' }}</small></div></div>
          <fieldset class="nt-form-scopes"><legend>ข้อมูลที่ต้องการเก็บ <span>* เลือกอย่างน้อย 1 ประเภท</span></legend><div><label v-for="scope in availableScopes" :key="scope.key"><input v-model="form.scopes" type="checkbox" :value="scope.key" />{{ scope.label }}</label></div></fieldset>
          <div class="nt-form-grid"><div><label for="nt-days">ช่วงข้อมูลย้อนหลัง</label><select id="nt-days" v-model.number="form.days"><option :value="7">7 วัน</option><option :value="30">30 วัน</option><option :value="90">90 วัน</option></select></div><div><label for="nt-depth">ความลึกเครือข่าย</label><select id="nt-depth" v-model.number="form.depth"><option v-for="depth in [1,2,3]" :key="depth" :value="depth">{{ depth }} ชั้น</option></select></div><div><label for="nt-priority">ลำดับความสำคัญ</label><select id="nt-priority" v-model="form.priority"><option v-for="(label,key) in priorityLabels" :key="key" :value="key">{{ label }}</option></select></div><div><label for="nt-frequency">รอบการเก็บที่ต้องการ</label><select id="nt-frequency" v-model="form.frequency"><option v-for="(label,key) in frequencyLabels" :key="key" :value="key">{{ label }}</option></select></div><div><label for="nt-tags">ป้ายกำกับ</label><input id="nt-tags" v-model="form.tagsText" maxlength="200" placeholder="เช่น เฝ้าติดตาม, โครงการ A" /><small>คั่นแต่ละป้ายด้วยเครื่องหมายจุลภาค</small></div><div><label for="nt-note">หมายเหตุ</label><input id="nt-note" v-model.trim="form.note" maxlength="300" placeholder="สิ่งที่ต้องการติดตามเพิ่มเติม" /></div></div>
          <div class="nt-mongo-note"><i class="fa fa-database" aria-hidden="true"></i><span><strong>ใช้ข้อมูลใน MongoDB ก่อนเสมอ</strong><small>เตรียมกราฟได้ทันทีเมื่อมีข้อมูล แล้วค่อยให้บอตเก็บข้อมูลใหม่ตามขอบเขตที่เลือก</small></span></div>
          <p v-if="formError" class="nt-error" role="alert">{{ formError }}</p>
          <div class="nt-form-footer"><span>บันทึกในเบราว์เซอร์เท่านั้น</span><button type="button" class="nt-secondary" @click="formOpen = false">ยกเลิก</button><button type="submit" class="nt-primary">{{ editingId ? 'บันทึกการแก้ไข' : 'บันทึกเป้าหมาย' }}</button></div>
        </form>
      </b-modal>
    </div>
  </div>
</template>

<script>
import HomeNav from "@/components/HomeNavMion.vue";
import { BModal } from "bootstrap-vue";

const STORAGE_KEY = "aion-network-targets-mock-v1";
const SCOPES = [{ key: "profile", label: "โปรไฟล์" }, { key: "posts", label: "โพสต์" }, { key: "comments", label: "ความคิดเห็น" }, { key: "mentions", label: "Mention / Tag" }, { key: "followers", label: "รายชื่อผู้ติดตาม" }, { key: "friends", label: "เพื่อน" }];
const seedTargets = () => [
  { id: "mock-t1", name: "สมชาย ก.", kind: "account", platform: "Facebook", value: "https://www.facebook.com/somchai.k", scopes: ["profile", "posts", "comments", "followers"], days: 30, depth: 2, priority: "high", frequency: "daily", tags: ["เฝ้าติดตาม", "กลุ่ม A"], note: "ตรวจข้อมูลเดิมก่อน และเติมรายชื่อผู้ติดตามเมื่อข้อมูลพร้อม", status: "ready", updatedLabel: "19 ต.ค. 2026 · 14:30" },
  { id: "mock-t2", name: "Urban Voice", kind: "account", platform: "X", value: "https://x.com/urbanvoice", scopes: ["profile", "posts", "mentions"], days: 7, depth: 1, priority: "normal", frequency: "daily", tags: ["ประเด็นเมือง"], note: "", status: "draft", updatedLabel: "" },
  { id: "mock-t3", name: "เมืองน่าอยู่", kind: "hashtag", platform: "Facebook", value: "เมืองน่าอยู่", scopes: ["posts", "comments", "mentions"], days: 30, depth: 1, priority: "high", frequency: "daily", tags: ["แฮชแท็ก"], note: "สำรวจบัญชีที่ร่วมใช้แฮชแท็กและ Impact", status: "queued", updatedLabel: "" },
  { id: "mock-t4", name: "มานี จ.", kind: "account", platform: "Instagram", value: "https://www.instagram.com/manee.j/", scopes: ["profile", "posts"], days: 30, depth: 1, priority: "normal", frequency: "weekly", tags: [], note: "พักการเก็บไว้ก่อน", status: "paused", updatedLabel: "18 ต.ค. 2026 · 09:10" },
  { id: "mock-t5", name: "ขนส่งสาธารณะ", kind: "hashtag", platform: "X", value: "ขนส่งสาธารณะ", scopes: ["posts", "mentions"], days: 7, depth: 1, priority: "normal", frequency: "once", tags: ["ประเด็นเมือง"], note: "", status: "draft", updatedLabel: "" },
];
const emptyForm = () => ({ kind: "account", name: "", platform: "Facebook", value: "", scopes: ["profile", "posts"], days: 30, depth: 1, priority: "normal", frequency: "once", tagsText: "", note: "" });
export default {
  name: "NetworkTargets", components: { HomeNav, BModal },
  data() { return { targets: seedTargets(), selectedIds: [], activeId: "mock-t1", search: "", typeFilter: "all", platformFilter: "all", statusFilter: "all", formOpen: false, editingId: null, form: emptyForm(), formError: "", message: "", platforms: ["Facebook", "X", "Instagram"], typeTabs: [{ key: "all", label: "ทั้งหมด" }, { key: "account", label: "บัญชี" }, { key: "hashtag", label: "แฮชแท็ก" }], statusLabels: { draft: "พร้อมเข้าคิว", queued: "อยู่ในคิวจำลอง", ready: "มีข้อมูลตัวอย่าง", paused: "พักการเก็บ" }, priorityLabels: { normal: "ปกติ", high: "สูง" }, frequencyLabels: { once: "ครั้งเดียว", daily: "ทุกวัน", weekly: "ทุกสัปดาห์" } }; },
  computed: {
    filteredTargets() { const search = this.search.trim().toLocaleLowerCase(); return this.targets.filter(target => (this.typeFilter === "all" || target.kind === this.typeFilter) && (this.platformFilter === "all" || target.platform === this.platformFilter) && (this.statusFilter === "all" || target.status === this.statusFilter) && (!search || `${target.name} ${target.value} ${target.tags.join(" ")}`.toLocaleLowerCase().includes(search))); },
    activeTarget() { return this.targets.find(target => target.id === this.activeId) || null; },
    selectedVisibleCount() { return this.filteredTargets.filter(target => this.selectedIds.includes(target.id)).length; },
    allVisibleSelected() { return this.filteredTargets.length > 0 && this.selectedVisibleCount === this.filteredTargets.length; },
    queueableSelected() { return this.targets.filter(target => this.selectedIds.includes(target.id) && ["draft", "ready"].includes(target.status)); },
    availableScopes() { return SCOPES.filter(scope => (this.form.kind === "account" || !["profile", "followers", "friends"].includes(scope.key)) && (scope.key !== "friends" || this.form.platform === "Facebook")); },
  },
  watch: {
    "form.platform"() { this.form.scopes = this.form.scopes.filter(key => this.availableScopes.some(scope => scope.key === key)); },
  },
  created() {
    try { const saved = JSON.parse(localStorage.getItem(STORAGE_KEY)); if (Array.isArray(saved) && saved.length && saved.every(item => item && typeof item.id === "string" && typeof item.name === "string" && typeof item.value === "string" && ["account", "hashtag"].includes(item.kind) && this.platforms.includes(item.platform) && Object.prototype.hasOwnProperty.call(this.statusLabels, item.status) && Array.isArray(item.scopes) && Array.isArray(item.tags))) { this.targets = saved; this.activeId = saved[0].id; } } catch (error) { this.message = "ไม่สามารถอ่านรายการที่บันทึกไว้ จึงแสดงข้อมูลตัวอย่างเริ่มต้น"; }
  },
  methods: {
    countStatus(status) { return this.targets.filter(target => target.status === status).length; },
    scopeLabel(key) { const scope = SCOPES.find(item => item.key === key); return scope ? scope.label : key; },
    persist() { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(this.targets)); return true; } catch (error) { this.message = "เปลี่ยนรายการในหน้านี้แล้ว แต่เบราว์เซอร์ไม่อนุญาตให้บันทึกไว้หลังรีโหลด"; return false; } },
    clearFilters() { this.search = ""; this.typeFilter = "all"; this.platformFilter = "all"; this.statusFilter = "all"; },
    selectVisible(checked) { const ids = this.filteredTargets.map(target => target.id); this.selectedIds = checked ? [...new Set([...this.selectedIds, ...ids])] : this.selectedIds.filter(id => !ids.includes(id)); },
    focusName() { this.$refs.nameInput.focus(); },
    openForm(target) { this.editingId = target ? target.id : null; this.form = target ? { ...target, scopes: target.scopes.slice(), tagsText: target.tags.join(", ") } : emptyForm(); this.formError = ""; this.formOpen = true; },
    setKind(kind) { if (this.form.kind === kind) return; this.form.kind = kind; this.form.value = ""; this.form.scopes = kind === "hashtag" ? ["posts", "mentions"] : ["profile", "posts"]; this.formError = ""; },
    normalizeValue(value, kind, platform) {
      if (kind === "hashtag") { const tag = value.normalize("NFKC").trim().replace(/^#+/, "").toLocaleLowerCase(); if (!tag || /\s|#/.test(tag)) throw new Error("กรอกแฮชแท็กเดียวโดยไม่เว้นวรรค"); return tag; }
